"use client";

import { useState, useEffect } from "react";
import { PiImageSquareLight } from "react-icons/pi";

export default function Admin() {
    const [password, setPassword] = useState("");
    const [accessGranted, setAccessGranted] = useState(false);
    const [experiences, setExperiences] = useState<ExperienceType[]>([]);
    const [editingExp, setEditingExp] = useState<ExperienceType | null>(null);
    const [coverFile, setCoverFile] = useState("");




    async function handleSubmit(e: React.FormEvent) {
        e.preventDefault();

        const res = await fetch("/api/admin", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ password }),
        });
        const data = await res.json();

        if (data.success) {
            setAccessGranted(true);
        } else {
            alert("wrong password");
        }
    }

    // Fetch experiences
    async function fetchExperiences() {
        const res = await fetch("/api/admin/experience");
        const data = await res.json();
        setExperiences(data);
    }

    // Add or update experience
    async function saveExperience(exp: ExperienceType) {
        const method = exp._id ? "PUT" : "POST";

        await fetch("/api/admin/experience", {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(exp),
        });
        fetchExperiences();
        setEditingExp(null);
    }

    // Delete experience
    async function deleteExperience(id: string) {
        await fetch("/api/experiences", {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id }),
        });
        fetchExperiences();
    }

    if (accessGranted) {
        return (
            <div className="flex justify-center flex-col items-center h-screen">
                <div className="flex justify-center items-center h-[70vh] w-full gap-5 flex-col">
                    <h1 className="text-[8vw] lg:text-[4vw] font-['Bad_Script']">Admin</h1>
                    <div className="flex justify-start items-center flex-col overflow-y-scroll scroll-hidden gap-5 w-[50vw] bubble p-10 rounded-4xl">
                        {experiences.map((exp) => (
                            <div className="flex w-full flex-row flex-grow justify-start gap-5 items-start bubble rounded-4xl pr-10" key={exp._id}>
                                <img className="rounded-4xl w-[10vw] aspect-[4/3]" src={exp.cover.url}/>
                                <div className="flex-col flex">
                                    <h1  className="w-full flex-row text-[1vw] line-clamp-1 pt-5">{exp.title}</h1>
                                    <p>
                                        {exp.dates.map(date =>
                                            (new Date(date)).toLocaleDateString("en-US", {
                                            month: "short",
                                            day: "numeric",
                                            year: "numeric"
                                        })).join(" - ")}
                                    </p>
                                    <p className="overflow-hidden w-full line-clamp-2">{exp.description}</p>
                                </div>
                    
                                <div className="flex ml-auto flex-col justify-between h-full items-end py-5">
                                    <button onClick={() => setEditingExp(exp)}>Edit</button>
                                    <button onClick={() => deleteExperience(exp._id)}>Delete</button>
                                </div>
                            </div>
                        ))}
                    </div>
                    <button className="rounded-full h-[5vh] bubble p-5 flex justify-center items-center" onClick={fetchExperiences}>Load Experiences</button>
                    {editingExp && (
                        <div className="fixed bg-[var(--opaque)] h-full w-full flex items-center justify-center p-5 z-100">
                            <div className="rounded-4xl h-[80vh] w-[60vw] gap-10 bg-[var(--background)] p-5 overflow-hidden">
                                <h2 className="text-2xl font-['Bad_Script'] pb-5 w-full">Edit Experience</h2>
                                <form
                                    onSubmit={(e) => {
                                    e.preventDefault();
                                    saveExperience(editingExp);
                                    }}
                                    className="flex flex-col h-[70vh] w-full gap-5 overflow-scroll"
                                >
                                    <div className="rounded-full w-full flex justify-center items-start gap-5">
                                        <input
                                            id="fileInput"
                                            type="file"
                                            className="hidden"
                                            onChange={(e) => {
                                                const file = e.target.files?.[0];
                                                if (file) {
                                                    const imageUrl = URL.createObjectURL(file);
                                                    setEditingExp({ ...editingExp, cover: ({url: imageUrl, type: "image"} as LinkType) });
                                                    setCoverFile(file.name);

                                                }
                                            }}
                                        />
                                        <label
                                            htmlFor="fileInput"
                                            className="rounded-full h-[5vh] flex-1 p-5 truncate flex justify-center items-center bubble">
                                            Choose Cover
                                        </label>
                                        <span className="rounded-full h-[5vh] flex-3 flex p-5 truncate overflow-scroll justify-start scroll-hidden items-center bubble">
                                            {editingExp.cover.url}
                                        </span>


                                    </div>
                                    <input
                                    type="text"
                                    placeholder="Title"
                                    className="bubble h-[5vh] rounded-4xl p-5 outline-none resize-none"
                                    value={editingExp.title || ""}
                                    onChange={(e) =>
                                        setEditingExp({ ...editingExp, title: e.target.value })
                                    }
                                    />
                                    <div className="flex justify-between gap-5">
                                        <div className="flex flex-row gap-2 h-[5vh] w-full justify-center bubble items-center rounded-full px-5">
                                            <p>start:</p>
                                            <input
                                            type="date"
                                            value={editingExp.dates?.[0] || ""}
                                            onChange={(e) =>
                                                setEditingExp({ ...editingExp, dates: [e.target.value, editingExp.dates?.[1]] })
                                            }
                                            />
                                        </div>
                                        
                                        <div className="flex flex-row gap-2 bubble h-[5vh] w-full justify-center items-center rounded-full px-5">
                                            <p>end:</p>
                                            <input
                                            type="date"
                                            value={editingExp.dates?.[1] || ""}
                                            onChange={(e) =>
                                                setEditingExp({ ...editingExp, dates: [editingExp.dates?.[0], e.target.value] })
                                            }
                                            />
                                        </div>
                                    </div>
                                    <textarea
                                    placeholder="Description"
                                    className="bubble h-[30vh] rounded-4xl p-5 outline-none resize-none"
                                    value={editingExp.description || ""}
                                    onChange={(e) =>
                                        setEditingExp({ ...editingExp, description: e.target.value })
                                    }
                                    />
                                    <button className="rounded-full h-[5vh] bubble p-5 w-full flex justify-center items-center" onClick={fetchExperiences}>Add tip</button>
                                    <textarea
                                    placeholder="Tips"
                                    className="bubble h-[20vh] rounded-4xl p-5 outline-none resize-none"
                                    value={editingExp.tips || ""}
                                    onChange={(e) =>
                                        setEditingExp({ ...editingExp, tips: [e.target.value] })
                                    }
                                    />
                                    <div className="flex justify-between">
                                        <button
                                            type="button"
                                            onClick={() => setEditingExp(null)}
                                            className="bubble sticky h-[5vh] rounded-full px-5"
                                        >
                                            Cancel
                                        </button>
                                        <button
                                            type="submit"
                                            className="bubble sticky h-[5vh] rounded-full px-5"
                                        >
                                            Save
                                    </button>
                                    </div>
                                </form>
                            </div>
                        </div>
                        )}
                </div>
            </div>
        );
        }

    return (
        <div className="flex justify-center items-center h-screen">
            <form className="flex justify-center items-center bubble rounded-full h-[5vh] px-5" onSubmit={handleSubmit}>
                <input
                    type="password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder="Enter password"
                />
                <button type="submit">Submit</button>
            </form>
        </div>
    );
    }
